  'reason','SYNTHETIC_PRIVATE_LEAVE_REQUEST_REASON')
$$;
create function pg_temp.rstate(p_action text,p_id text,p_balance bigint default null)
returns jsonb language sql as $$
 select jsonb_build_object('action',p_action,'id',pg_temp.wid(p_id),
  'employee_id',pg_temp.wid('employee'),'reason','Synthetic decision')||
  case when p_balance is null then '{}'::jsonb
   else jsonb_build_object('balance_version',p_balance) end
$$;
