select is((api.people_leave_balance(pg_temp.wid('tenant'),pg_temp.wid('entity'),
 pg_temp.wid('branch'),pg_temp.wid('employee'),pg_temp.wid('SYCARRY'),pg_temp.wdate())
 #>>'{account_version}'),'2','AC-406 carry advances account version');
select throws_ok($$select pg_temp.lg(jsonb_build_object('action','carry',
 'id',pg_temp.wid('carry-duplicate'),'employee_id',pg_temp.wid('employee'),
 'policy_version_id',pg_temp.wid('SYCARRY.v2'),
 'prior_version_id',pg_temp.wid('SYCARRY.v1'),'boundary_date',pg_temp.wdate(),
 'reason','Duplicate carry'),2,'carry-duplicate-command')$$,
 '23505',null,'AC-406 carry boundary cannot post twice');
reset role;
select is((select source_seconds::text||':'||carried_seconds::text from people.leave_carry_events
 where id=pg_temp.wid('carry-event')),'28800:7200',
 'AC-406 carry preserves source and cap evidence');

-- Attendance and leave must compete through the same approved segment arbiter.
create function pg_temp.la(p jsonb,v bigint,k text) returns jsonb language sql as $$
 select api.people_attendance_command(pg_temp.wid('tenant'),pg_temp.wid('entity'),
 pg_temp.wid('branch'),pg_temp.wid(k),pg_temp.wid(k),now(),p,v)
$$;
select pg_temp.wactor('creator');
set local role authenticated;
insert into leave_responses values('cross-attendance',pg_temp.la(
 (pg_temp.request('cross-attendance',14)-'policy_version_id')||
 jsonb_build_object('breaks','[]'::jsonb),0,'cross-attendance-create'));
insert into leave_responses values('cross-attendance-submit',pg_temp.la(
 pg_temp.rstate('submit','cross-attendance'),1,'cross-attendance-submit'));
select pg_temp.wactor('reviewer');
insert into leave_responses values('cross-attendance-approve',pg_temp.la(
 pg_temp.rstate('approve','cross-attendance'),2,'cross-attendance-approve'));
select pg_temp.wactor('creator');
insert into leave_responses values('cross-leave',pg_temp.lr(
 pg_temp.request('cross-leave',14),0,'cross-leave-create'));
insert into leave_responses values('cross-leave-submit',pg_temp.lr(
 pg_temp.rstate('submit','cross-leave'),1,'cross-leave-submit'));
select pg_temp.wactor('reviewer');
select throws_ok($$select pg_temp.lr(pg_temp.rstate('approve','cross-leave',
 (api.people_leave_balance(pg_temp.wid('tenant'),pg_temp.wid('entity'),
 pg_temp.wid('branch'),pg_temp.wid('employee'),pg_temp.wid('SYNLEAVE'),pg_temp.wdate())
 ->>'account_version')::bigint),2,'cross-leave-approve')$$,
 '23514','WORK_INTERVAL_CONFLICT','AC-411 attendance prevents overlapping leave approval');
reset role;
select is((select status from people.leave_requests where id=pg_temp.wid('cross-leave')),
 'submitted','AC-411 interval conflict preserves the pending leave request');
select is((select count(*)::text from people.leave_effects
 where request_id=pg_temp.wid('cross-leave')),'0',
 'AC-411 interval conflict commits no leave debit');

-- Unpaid leave is permitted only by an explicit immutable synthetic policy.
select pg_temp.wactor('creator');
set local role authenticated;
insert into leave_responses values('unpaid-policy',pg_temp.lp(
 pg_temp.policy('SYUNPAID')||jsonb_build_object('allow_unpaid',true),0,'unpaid-policy'));
insert into leave_responses values('unpaid-request',pg_temp.lr(
 pg_temp.request('unpaid-request',21)||jsonb_build_object(
 'policy_version_id',pg_temp.wid('SYUNPAID.v1')),0,'unpaid-create'));
insert into leave_responses values('unpaid-submit',pg_temp.lr(
 pg_temp.rstate('submit','unpaid-request'),1,'unpaid-submit'));
select pg_temp.wactor('reviewer');
insert into leave_responses values('unpaid-approve',pg_temp.lr(
 pg_temp.rstate('approve','unpaid-request',0),2,'unpaid-approve'));
select is((select response#>>'{entity,unpaid_seconds}' from leave_responses
 where name='unpaid-approve'),'28800','AC-406 explicit unpaid policy freezes uncovered charge');
select is((api.people_leave_balance(pg_temp.wid('tenant'),pg_temp.wid('entity'),
 pg_temp.wid('branch'),pg_temp.wid('employee'),pg_temp.wid('SYUNPAID'),pg_temp.wdate())
 ->>'available_seconds'),'0','AC-406 unpaid approval invents no entitlement');
insert into leave_responses values('unpaid-cancel',pg_temp.lr(
 pg_temp.rstate('cancel','unpaid-request',1),3,'unpaid-cancel'));
select is((select response#>>'{entity,status}' from leave_responses
 where name='unpaid-cancel'),'cancelled','AC-406 unpaid cancellation preserves history');
reset role;
select is((select count(*)::text from people.leave_effects
 where request_id=pg_temp.wid('unpaid-request')),'0',
 'AC-406 unpaid cancellation invents no balance credit');

select pg_temp.wactor('creator');
set local role authenticated;
select is(api.people_leave_policy_for_version(pg_temp.wid('tenant'),pg_temp.wid('entity'),
 pg_temp.wid('branch'),pg_temp.wid('SYUNPAID.v1'))#>>'{policy,id}',
 pg_temp.wid('SYUNPAID')::text,'AC-419 recovered policy version resolves its scoped balance identity');
select throws_ok($$select api.people_leave_policy_for_version(pg_temp.wid('tenant'),
 pg_temp.wid('entity'),pg_temp.wid('branch'),pg_temp.wid('absent-policy-version'))$$,
 'P0002',null,'AC-401 version lookup reveals no absent policy');
reset role;
delete from core.role_permissions where tenant_id=pg_temp.wid('tenant')
 and role_id=pg_temp.wid('creator.role') and permission_code='people.leave.manage';
select pg_temp.wactor('creator');
set local role authenticated;
select throws_ok($$select pg_temp.lr(pg_temp.request('leave-request'),0,'request-create')$$,
 '42501',null,'AC-401 revoked permission rejects even an exact leave replay');
select throws_ok($$select api.people_leave_own_receipt(pg_temp.wid('tenant'),
 pg_temp.wid('entity'),pg_temp.wid('branch'),pg_temp.wid('request-create'))$$,
 '42501',null,'AC-401 revoked capability prevents receipt reconciliation');
reset role;

do $$declare v_failed text;begin
 select string_agg(message,chr(10)) into v_failed from leave_assertions where message like 'not ok%';
 if v_failed is not null then raise exception using errcode='P0001',message=v_failed;end if;
end $$;
set constraints all immediate;
select * from finish(true);
rollback;
